/* Scans assets/products/<product-slug>/ and writes assets/products/manifest.js so the storefront
   shows real photographs instead of illustrations.

   Run from the prototype folder:   node tools/build-photo-manifest.js

   File naming inside assets/products/<product-slug>/
     1.jpg, 2.jpg, 3.jpg            shots shared by every colour (shown in numeric order)
     burgundy__1.jpg, burgundy__2.jpg   shots of one colour (name lower-cased, spaces -> "-")
                                    e.g. dusty-rose__1.jpg, powder-blue__1.jpg
   When a shopper picks a colour, that colour's shots come first, then the shared ones.
   A colour with no shots of its own falls back to the shared shots (or the illustration if none).
   Accepted: .jpg .jpeg .png .webp .avif   Avoid spaces in file names. */
'use strict';
const fs = require('fs');
const path = require('path');

require('../js/seed.js');
const { PRODUCTS } = globalThis.BFSeed;

const base = path.join(__dirname, '..', 'assets', 'products');
const IMG = /\.(jpe?g|png|webp|avif)$/i;
const slugColor = (c) => c.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
const natural = (a, b) => a.localeCompare(b, undefined, { numeric: true });

const out = {};
let files = 0;
const warnings = [];

PRODUCTS.forEach((p) => {
  const dir = path.join(base, p.slug);
  if (!fs.existsSync(dir)) return;
  const entry = { shared: [], colors: {} };
  fs.readdirSync(dir).filter((f) => IMG.test(f)).sort(natural).forEach((f) => {
    const rel = 'assets/products/' + p.slug + '/' + encodeURIComponent(f);
    const m = f.replace(IMG, '').match(/^(.+?)__\d+$/);
    files += 1;
    if (!m) { entry.shared.push(rel); return; }
    const colour = p.colors.find((c) => slugColor(c) === m[1].toLowerCase());
    if (!colour) { warnings.push(`${p.slug}/${f}: no colour "${m[1]}" on this product (colours: ${p.colors.map(slugColor).join(', ')}) - treated as a shared shot`); entry.shared.push(rel); return; }
    (entry.colors[colour] = entry.colors[colour] || []).push(rel);
  });
  if (entry.shared.length || Object.keys(entry.colors).length) out[p.slug] = entry;
});

// home-page hero: assets/hero/1.jpg, 2.jpg (up to three are shown side by side)
const heroDir = path.join(__dirname, '..', 'assets', 'hero');
if (fs.existsSync(heroDir)) {
  const shots = fs.readdirSync(heroDir).filter((f) => IMG.test(f)).sort(natural).map((f) => 'assets/hero/' + encodeURIComponent(f));
  if (shots.length) { out.__hero = shots; files += shots.length; }
}

// "Our story" section on the home page: assets/story/1.jpg
const storyDir = path.join(__dirname, '..', 'assets', 'story');
if (fs.existsSync(storyDir)) {
  const shots = fs.readdirSync(storyDir).filter((f) => IMG.test(f)).sort(natural).map((f) => 'assets/story/' + encodeURIComponent(f));
  if (shots.length) { out.__story = shots; files += shots.length; }
}

// folders that do not match any product slug are probably typos
if (fs.existsSync(base)) {
  fs.readdirSync(base, { withFileTypes: true }).filter((d) => d.isDirectory() && !PRODUCTS.some((p) => p.slug === d.name))
    .forEach((d) => warnings.push(`folder "${d.name}" does not match any product slug and was ignored`));
}

const header = '/* Product photograph manifest — GENERATED by tools/build-photo-manifest.js. Do not edit by hand. */\n';
fs.writeFileSync(path.join(base, 'manifest.js'), header + 'window.BF_PHOTOS = ' + JSON.stringify(out, null, 2) + ';\n');
console.log(`manifest.js written: ${Object.keys(out).filter((k) => !k.startsWith('__')).length} product(s) with photographs, ${out.__hero ? out.__hero.length : 0} hero photo(s), ${files} image file(s) in total.`);
const missing = PRODUCTS.filter((p) => !out[p.slug]);
if (missing.length) console.log(`${missing.length} product(s) have no photograph yet and show the "photograph coming soon" placeholder: ${missing.map((p) => p.slug).join(', ')}`);
warnings.forEach((w) => console.warn('warning: ' + w));
